    {
      "drone_id": "drone_1",
      "path": [
        {
          "x": 50,
          "y": 50,
          "t": 0.0,
          "action": "PICKUP",
          "delivery_ids": [
            "d1",
            "d2"
          ]
        },
        {
          "x": 70,
