Here are complete C programs for all three parts of your assignment:

---

## Part a) Round Robin Scheduling (Quantum = 1)

```c
#include <stdio.h>
#include <string.h>

int main() {
    int n = 5;
    int quantum = 1;

    char names[5][5] = {"P1", "P2", "P3", "P4", "P5"};
    int burst[]     = {10, 1, 2, 1, 5};
    int arrival[]   = {0,  0, 0, 0, 0};
    int remaining[] = {10, 1, 2, 1, 5};

    int completion[5] = {0};
    int wt[5] = {0}, tat[5] = {0};

    int time = 0, done = 0;

    printf("=== Round Robin Scheduling (Quantum = %d) ===\n\n", quantum);
    printf("Gantt Chart:\n|");

    while (done < n) {
        int idle = 1;
        for (int i = 0; i < n; i++) {
            if (remaining[i] > 0 && arrival[i] <= time) {
                idle = 0;
                printf(" %s |", names[i]);
                remaining[i] -= quantum;
                time += quantum;
                if (remaining[i] <= 0) {
                    completion[i] = time;
                    done++;
                }
            }
        }
        if (idle) time++;  // CPU idle
    }

    printf("\n\n");
    printf("%-10s %-6s %-6s %-6s %-6s %-6s\n",
           "Process", "AT", "BT", "CT", "TAT", "WT");
    printf("------------------------------------------\n");

    double totalWT = 0, totalTAT = 0;
    for (int i = 0; i < n; i++) {
        tat[i] = completion[i] - arrival[i];
        wt[i]  = tat[i] - burst[i];
        totalTAT += tat[i];
        totalWT  += wt[i];
        printf("%-10s %-6d %-6d %-6d %-6d %-6d\n",
               names[i], arrival[i], burst[i], completion[i], tat[i], wt[i]);
    }

    printf("------------------------------------------\n");
    printf("Average Turnaround Time = %.2f\n", totalTAT / n);
    printf("Average Waiting Time    = %.2f\n", totalWT  / n);

    return 0;
}
```

### Output:
```
=== Round Robin Scheduling (Quantum = 1) ===

Gantt Chart:
| P1 | P2 | P3 | P4 | P5 | P1 | P3 | P5 | P1 | P5 | P1 | P5 | P1 | P5 | P1 | P1 | P1 | P1 | P1 |

Process    AT     BT     CT     TAT    WT
------------------------------------------
P1         0      10     19     19     9
P2         0      1      2      2      1
P3         0      2      7      7      5
P4         0      1      4      4      3
P5         0      5      14     14     9
------------------------------------------
Average Turnaround Time = 9.20
Average Waiting Time    = 5.40
```

