## Part b-i) SJF — Shortest Job First (Non-Preemptive)

```c
#include <stdio.h>
#include <limits.h>

int main() {
    int n = 5;

    char names[5][5] = {"P0", "P1", "P2", "P3", "P4"};
    int arrival[]    = {0, 1, 2, 3, 4};
    int burst[]      = {4, 3, 1, 5, 2};
    int remaining[]  = {4, 3, 1, 5, 2};

    int completion[5] = {0};
    int wt[5] = {0}, tat[5] = {0};
    int finished[5]   = {0};

    int time = 0, done = 0;

    printf("=== SJF Scheduling (Non-Preemptive) ===\n\n");
    printf("Gantt Chart:\n|");

    while (done < n) {
        int idx = -1, minBurst = INT_MAX;

        for (int i = 0; i < n; i++) {
            if (!finished[i] && arrival[i] <= time) {
                if (burst[i] < minBurst) {
                    minBurst = burst[i];
                    idx = i;
                }
            }
        }

        if (idx == -1) {
            time++;  // CPU idle
            continue;
        }

        // Run selected process to completion (non-preemptive)
        for (int t = 0; t < burst[idx]; t++) {
            printf(" %s |", names[idx]);
        }

        time += burst[idx];
        completion[idx] = time;
        finished[idx]   = 1;
        done++;
    }

    printf("\n\n");
    printf("%-10s %-6s %-6s %-6s %-6s %-6s\n",
           "Process", "AT", "BT", "CT", "TAT", "WT");
    printf("------------------------------------------\n");

    double totalWT = 0, totalTAT = 0;
    for (int i = 0; i < n; i++) {
        tat[i] = completion[i] - arrival[i];
        wt[i]  = tat[i] - burst[i];
        totalTAT += tat[i];
        totalWT  += wt[i];
        printf("%-10s %-6d %-6d %-6d %-6d %-6d\n",
               names[i], arrival[i], burst[i], completion[i], tat[i], wt[i]);
    }

    printf("------------------------------------------\n");
    printf("Average Turnaround Time = %.2f\n", totalTAT / n);
    printf("Average Waiting Time    = %.2f\n", totalWT  / n);

    return 0;
}
```

### Output:
```
=== SJF Scheduling (Non-Preemptive) ===

Gantt Chart:
| P0 | P0 | P0 | P0 | P2 | P4 | P4 | P1 | P1 | P1 | P3 | P3 | P3 | P3 | P3 |

Process    AT     BT     CT     TAT    WT
------------------------------------------
P0         0      4      4      4      0
P1         1      3      10     9      6
P2         2      1      5      3      2
P3         3      5      15     12     7
P4         4      2      7      3      1
------------------------------------------
Average Turnaround Time = 6.20
Average Waiting Time    = 3.20
```

---

## Part b-ii) SRTF — Shortest Remaining Time First (Preemptive SJF)

```c
#include <stdio.h>
#include <limits.h>

int main() {
    int n = 5;

    char names[5][5] = {"P0", "P1", "P2", "P3", "P4"};
    int arrival[]    = {0, 1, 2, 3, 4};
    int burst[]      = {4, 3, 1, 5, 2};
    int remaining[]  = {4, 3, 1, 5, 2};

    int completion[5] = {0};
    int wt[5] = {0}, tat[5] = {0};
    int finished[5]   = {0};

    int time = 0, done = 0;
    int prev = -1;  // track Gantt chart changes

    printf("=== SRTF Scheduling (Preemptive SJF) ===\n\n");
    printf("Gantt Chart:\n");

    int maxTime = 0;
    for (int i = 0; i < n; i++) maxTime += burst[i];

    printf("|");
    while (done < n) {
        int idx = -1, minRem = INT_MAX;

        for (int i = 0; i < n; i++) {
            if (!finished[i] && arrival[i] <= time) {
                if (remaining[i] < minRem) {
                    minRem = remaining[i];
                    idx = i;
                }
            }
        }

        if (idx == -1) {
            time++;
            continue;
        }

        if (idx != prev) {
            if (prev != -1) printf(" |");
            printf(" %s", names[idx]);
            prev = idx;
        }

        remaining[idx]--;
        time++;

        if (remaining[idx] == 0) {
            completion[idx] = time;
            finished[idx]   = 1;
            done++;
            prev = -1;
            printf(" |");
        }
    }

    printf("\n\n");
    printf("%-10s %-6s %-6s %-6s %-6s %-6s\n",
           "Process", "AT", "BT", "CT", "TAT", "WT");
    printf("------------------------------------------\n");

    double totalWT = 0, totalTAT = 0;
    for (int i = 0; i < n; i++) {
        tat[i] = completion[i] - arrival[i];
        wt[i]  = tat[i] - burst[i];
        totalTAT += tat[i];
        totalWT  += wt[i];
        printf("%-10s %-6d %-6d %-6d %-6d %-6d\n",
               names[i], arrival[i], burst[i], completion[i], tat[i], wt[i]);
    }

    printf("------------------------------------------\n");
    printf("Average Turnaround Time = %.2f\n", totalTAT / n);
    printf("Average Waiting Time    = %.2f\n", totalWT  / n);

    return 0;
}
```

