    setLoading(true)
    try {
      const res  = await fetch(`${API}/candidates/${stage}`)
      const data = await res.json()
      setCandidates(data)
    } catch (e) {
      showMessage("Failed to fetch candidates.", "error")
    } finally {
      setLoading(false)
    }
  }, [])

  // ── Fetch counts for all tabs ─────────────────────────
  const fetchCounts = useCallback(async () => {
    const updated = {}
    await Promise.all(
      STAGES.map(async stage => {
        const res  = await fetch(`${API}/candidates/${stage}`)
        const data = await res.json()
        updated[stage] = data.length
      })
    )
    setCounts(updated)
  }, [])

  // ── On tab change ─────────────────────────────────────
  useEffect(() => {
    fetchCandidates(activeTab)
  }, [activeTab, fetchCandidates])

  // ── On mount ──────────────────────────────────────────
  useEffect(() => {
    fetchCounts()
  }, [fetchCounts])

  // ── Show temporary message ────────────────────────────
  const showMessage = (text, type = "info") => {
    setMessage({ text, type })
    setTimeout(() => setMessage(null), 4000)
  }

  // ── Run pipeline ──────────────────────────────────────
  const runPipeline = async () => {
    if (!jd || jd.trim() === "") {
      showMessage("Please enter a job description first.", "error")
      return
    }
    setRunning(true)
    showMessage("Pipeline running... this may take a few minutes.", "info")
    try {
      const res  = await fetch(`${API}/pipeline/run`, {
        method:  "POST",
        headers: { "Content-Type": "application/json" },
        body:    JSON.stringify({ job_description: jd }),
      })
      const data = await res.json()
      showMessage(data.message, "success")
      await fetchCounts()
      fetchCandidates(activeTab)
    } catch (e) {
      showMessage("Pipeline failed. Check backend terminal.", "error")
    } finally {
      setRunning(false)
    }
  }

  // ── Summary cards ─────────────────────────────────────
  const total = Object.values(counts).reduce((a, b) => a + b, 0)

  return (
    <div>

      {/* ── Summary cards ──────────────────────────────── */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        {STAGES.map(stage => (
          <SummaryCard
            key={stage}
            stage={stage}
            count={counts[stage] ?? 0}
            onClick={() => setActiveTab(stage)}
          />
        ))}
      </div>

      {/* ── Message banner ─────────────────────────────── */}
      {message && (
        <div className={`px-4 py-3 rounded-lg mb-4 text-sm font-medium
          ${message.type === "success" ? "bg-green-900 text-green-200"
          : message.type === "error"   ? "bg-red-900 text-red-200"
          :                              "bg-blue-900 text-blue-200"}`}>
          {message.text}
        </div>
      )}

      {/* ── Run pipeline button ────────────────────────── */}
      <div className="flex justify-between items-center mb-4">
        <p className="text-gray-400 text-sm">
          {total} total candidate{total !== 1 ? "s" : ""} across all stages
        </p>
        <button
          onClick={runPipeline}
          disabled={running}
          className="flex items-center gap-2 bg-blue-600
                     hover:bg-blue-700 disabled:bg-gray-700
                     disabled:cursor-not-allowed px-5 py-2
                     rounded-lg font-medium text-sm transition"
        >
          {running
            ? <>
                <span className="w-4 h-4 border-2 border-white
                                 border-t-transparent rounded-full
                                 animate-spin"/>
                Running...
              </>
            : "▶ Run Pipeline"
          }
        </button>
      </div>

      {/* ── Stage tabs ─────────────────────────────────── */}
      <div className="flex flex-wrap gap-2 mb-4">
        {STAGES.map(stage => (
          <StageTab
            key={stage}
            stage={stage}
            activeTab={activeTab}
            count={counts[stage]}
            onClick={setActiveTab}
          />
        ))}
      </div>

      {/* ── Candidate table ────────────────────────────── */}
      {loading
        ? <LoadingSpinner />
        : <CandidateTable candidates={candidates} stage={activeTab} />
      }

    </div>
  )
}

