```cpp
class Solution {
public:
    string shortestPalindrome(string s) {
        if(s.length()==0){
            return s;
        }
        string change = "";
        for (int i = s.length() - 1; i >= 1; i--) {
            change += s[i];
        }
        string added = change + s;
        vector<string> appending;
        char ch=added[0];
        string space="";
        space+=ch;
        appending.push_back(space);
        for (int i = 1; i < added.length(); i++) {
            appending.push_back(appending[i - 1] + added[i]);
        }
        string ans;
        for (int i = 0; i < appending.size(); i++) {
            if (appending[i].contains(s)) {
                ans = appending[i];
                break;
            }
        }
        return ans;
    }
};
