You're right — the algorithmic complexity can't really drop below O(N log N) here (binary search per vehicle is necessary since interference sums aren't monotonic across `j`, so two pointers won't work directly). But the **code itself** can be made much simpler by noticing a trick:

**The right-reach and left-reach problems are the same problem, just mirrored.**

So instead of writing separate binary-search logic for left and right, solve it **once** (rightward), then reverse the array and run the *exact same function* again to get leftward reach for free.

```cpp
#include <bits/stdc++.h>
using namespace std;

// For each j, finds the farthest index R (R >= j) such that
// sum(S[j+1..R]) <= S[j]. Returns R (or j if nothing reachable).
vector<int> farthestRight(vector<long long>& S, int N){
    vector<long long> prefix(N+1, 0);
    for(int i = 1; i <= N; i++) prefix[i] = prefix[i-1] + S[i];

    vector<int> R(N+1);
    for(int j = 1; j <= N; j++){
        long long target = S[j] + prefix[j];
        int m = int(upper_bound(prefix.begin()+j, prefix.begin()+N+1, target) - prefix.begin()) - 1;
        R[j] = m; // farthest reachable index (>= j)
    }
    return R;
}

int main(){
    int T;
    scanf("%d", &T);
    while(T--){
        int N;
        scanf("%d", &N);
        vector<long long> S(N+1);
        for(int i = 1; i <= N; i++) scanf("%lld", &S[i]);

        vector<long long> diff(N+2, 0);

        // ---- Rightward reach ----
        vector<int> right = farthestRight(S, N);
        for(int j = 1; j <= N; j++){
            if(right[j] > j){
                diff[j+1] += 1;
                diff[right[j]+1] -= 1;
            }
        }

        // ---- Leftward reach: just reverse the array and reuse the same function ----
        vector<long long> Srev(N+1);
        for(int i = 1; i <= N; i++) Srev[i] = S[N+1-i];
        vector<int> leftRev = farthestRight(Srev, N);

        for(int jr = 1; jr <= N; jr++){
            int j = N + 1 - jr;              // real index
            int Lrev = leftRev[jr];          // farthest reach in reversed coords
            int L = N + 1 - Lrev;             // convert back to real index
            if(L < j){
                diff[L] += 1;
                diff[j] -= 1;
            }
        }

        vector<long long> ans(N+1);
        long long cur = 0;
        for(int i = 1; i <= N; i++){
            cur += diff[i];
            ans[i] = cur;
        }

        for(int i = 1; i <= N; i++)
            printf("%lld%c", ans[i], (i==N) ? '\n' : ' ');
    }
    return 0;
}
```

**Why this is simpler to reason about:**
- Only one binary-search routine to get right (and trust).
- Leftward is just "solve the mirrored array" — no separate off-by-one logic to debug twice.
- Same O(N log N) complexity, same diff-array trick, just half the custom logic to verify for correctness.

