#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int BITS = 30; // adjust to 31+ if w_i / k can exceed ~2^30 - check your constraints!

struct Node{ int ch[2]; int cnt; };

int main(){
    int T;
    scanf("%d",&T);
    while(T--){
        int N,Q;
        scanf("%d %d",&N,&Q);
        vector<ll> w(N+1);
        for(int i=1;i<=N;i++) scanf("%lld",&w[i]);
        vector<vector<int>> adj(N+1);
        for(int i=0;i<N-1;i++){
            int x,y; scanf("%d %d",&x,&y);
            adj[x].push_back(y);
            adj[y].push_back(x);
        }

        // ---- iterative DFS: pre-order tin, subtree range end tout ----
        vector<int> tin(N+1), tout(N+1), order; order.reserve(N);
        vector<bool> visited(N+1,false);
        vector<int> stkNode; stkNode.push_back(1);
        vector<size_t> stkIt; stkIt.push_back(0);
        visited[1]=true;
        int timer=0;
        tin[1]=++timer; order.push_back(1);
        while(!stkNode.empty()){
            int u = stkNode.back();
            size_t &it = stkIt.back();
            if(it < adj[u].size()){
                int v = adj[u][it++];
                if(!visited[v]){
                    visited[v]=true;
                    tin[v]=++timer;
                    order.push_back(v);
                    stkNode.push_back(v);
                    stkIt.push_back(0);
                }
            } else {
                tout[u]=timer;
                stkNode.pop_back();
                stkIt.pop_back();
            }
        }

        // ---- persistent trie over weights, inserted in tin order ----
        vector<Node> pool;
        pool.push_back({{0,0},0}); // sentinel/null
        vector<int> root(N+1);
        root[0]=0;

        unordered_map<ll, vector<pair<int,int>>> groups; // value -> (tin, vertexId), sorted by tin
        groups.reserve(N*2);

        function<int(int,int,ll)> insertFn = [&](int prev, int bit, ll val)->int{
            int cur = (int)pool.size();
            pool.push_back(pool[prev]);
            pool[cur].cnt = pool[prev].cnt + 1;
            if(bit<0) return cur;
            int b = (int)((val>>bit)&1);
            pool[cur].ch[b] = insertFn(pool[prev].ch[b], bit-1, val);
            return cur;
        };

        for(int i=1;i<=N;i++){
            int v = order[i-1];
            ll val = w[v];
            root[i] = insertFn(root[i-1], BITS-1, val);
            groups[val].push_back({i, v});
        }

        // ---- sparse tables per value-group for range-min vertex id ----
        unordered_map<ll, vector<vector<int>>> sparse;
        unordered_map<ll, vector<int>> groupTin;
        for(auto &pr: groups){
            ll val = pr.first;
            auto &vp = pr.second;
            int len = (int)vp.size();
            vector<int> tins(len), ids(len);
            for(int i=0;i<len;i++){ tins[i]=vp[i].first; ids[i]=vp[i].second; }
            int LOG=1; while((1<<LOG) <= len) LOG++;
            vector<vector<int>> table(LOG, vector<int>(len));
            table[0]=ids;
            for(int j=1;j<LOG;j++)
                for(int i=0;i+(1<<j)<=len;i++)
                    table[j][i]=min(table[j-1][i], table[j-1][i+(1<<(j-1))]);
            sparse[val]=move(table);
            groupTin[val]=move(tins);
        }

        auto queryMinId=[&](ll val,int L,int R)->int{
            auto itT=groupTin.find(val);
            if(itT==groupTin.end()) return -1;
            vector<int> &tins=itT->second;
            int lo=int(lower_bound(tins.begin(),tins.end(),L)-tins.begin());
            int hi=int(upper_bound(tins.begin(),tins.end(),R)-tins.begin());
            if(lo>=hi) return -1;
            int len=hi-lo;
            int k=31-__builtin_clz((unsigned)len);
            auto &table=sparse[val];
            return min(table[k][lo], table[k][hi-(1<<k)]);
        };

        auto queryMaxXor=[&](int L,int R,ll k)->pair<int,ll>{
            int curR=root[R], curL=root[L-1];
            ll valStar=0, xorVal=0;
            for(int bit=BITS-1;bit>=0;bit--){
                int kb=(int)((k>>bit)&1);
                int want=kb^1;
                int cRw=pool[curR].ch[want], cLw=pool[curL].ch[want];
                int availW=pool[cRw].cnt - pool[cLw].cnt;
                int b;
                if(availW>0){ b=want; curR=cRw; curL=cLw; }
                else {
                    b=want^1;
                    curR=pool[curR].ch[b]; curL=pool[curL].ch[b];
                }
                valStar |= (ll)b<<bit;
                xorVal  |= (ll)(b^kb)<<bit;
            }
            int vid = queryMinId(valStar, L, R);
            return {vid, xorVal};
        };

        ll xl=0; int vl=0;
        for(int q=0;q<Q;q++){
            ll a,b;
            scanf("%lld %lld",&a,&b);
            ll v = a ^ (ll)vl;
            ll k = b ^ xl;
            int L=tin[(int)v], R=tout[(int)v];
            auto res=queryMaxXor(L,R,k);
            vl=res.first; xl=res.second;
            printf("%d %lld\n", vl, xl);
        }
    }
    return 0;
}
```

